import sys
from collections import deque

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    N, M = map(int, data[0].split())
    grid = [list(data[i + 1]) for i in range(N)]

    start = None
    for j, ch in enumerate(grid[0]):
        if ch == 'o':
            start = (0, j)
            break

    q = deque([start])
    while q:
        x, y = q.popleft()
        if x + 1 < N:
            below = grid[x + 1][y]
            if below == '.':
                grid[x + 1][y] = 'o'
                q.append((x + 1, y))
            elif below == '#':
                if y - 1 >= 0 and grid[x][y - 1] == '.':
                    grid[x][y - 1] = 'o'
                    q.append((x, y - 1))
                if y + 1 < M and grid[x][y + 1] == '.':
                    grid[x][y + 1] = 'o'
                    q.append((x, y + 1))

    sys.stdout.write('\n'.join(''.join(row) for row in grid))

if __name__ == "__main__":
